def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    def calculate_combined_cost(current_node, node, destination_node, distance_matrix, remaining_nodes):
        weight_immediate = 0.7 + 0.3 * (len(remaining_nodes) / (len(remaining_nodes) + 1))
        weight_future = 0.3 - 0.3 * (len(remaining_nodes) / (len(remaining_nodes) + 1))
        return weight_immediate * distance_matrix[current_node][node] + weight_future * distance_matrix[node][destination_node]

    min_cost = float('inf')
    next_node = None
    for node in unvisited_nodes:
        combined_cost = calculate_combined_cost(current_node, node, destination_node, distance_matrix, unvisited_nodes)
        if combined_cost < min_cost:
            min_cost = combined_cost
            next_node = node
    return next_node

def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    if destination_node in unvisited_nodes:
        return destination_node
    farthest_to_dest = max(unvisited_nodes, key=lambda node: distance_matrix[node][destination_node])
    penalty = {node: distance_matrix[current_node][node] + 0.2 * distance_matrix[node][farthest_to_dest] for node in unvisited_nodes}
    next_node = min(unvisited_nodes, key=penalty.get)
    return next_node
